/**
 * Unit tests for authentication middleware
 * @module middleware/auth
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import jwt from 'jsonwebtoken';
import type { Request, Response } from 'express';
import {
  configureAuth,
  parseTestToken,
  authenticateToken,
  validateApiKey,
  apiKeyCache,
  type UserPayload,
} from '../middleware/auth';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const TEST_SECRET = 'unit-test-jwt-secret';

function makeReq(overrides: Partial<Request> = {}): Request {
  return {
    headers: {},
    get: function (name: string) {
      return (this as any).headers[name?.toLowerCase()];
    },
    ...overrides,
  } as unknown as Request;
}

function makeRes(): Response & { _status: number; _json: any } {
  const res: any = {
    _status: 0,
    _json: null,
    status(code: number) {
      res._status = code;
      return res;
    },
    json(body: any) {
      res._json = body;
      return res;
    },
  };
  return res;
}

function buildTestToken(payload: Record<string, unknown>): string {
  const base64 = Buffer.from(JSON.stringify(payload)).toString('base64');
  return `test_token_${base64}`;
}

function signJwt(payload: object, _secret = TEST_SECRET, options?: jwt.SignOptions): string {
  // KS-184: the gateway verifies RS256-only. Sign with the test private key
  // (matching JWT_PUBLIC_KEY from vitest.setup.ts) so the middleware accepts it.
  // The legacy `secret` arg is ignored (kept for call-site compatibility).
  const privatePem = process.env.__TEST_JWT_PRIVATE_PEM as string;
  return jwt.sign(payload, privatePem, { algorithm: 'RS256', ...options });
}

// ---------------------------------------------------------------------------
// Mock fetch (used by validateApiKey)
// ---------------------------------------------------------------------------

const fetchMock = vi.fn();
vi.stubGlobal('fetch', fetchMock);

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('auth middleware', () => {
  beforeEach(() => {
    vi.stubEnv('NODE_ENV', 'test');
    apiKeyCache.clear();
    fetchMock.mockReset();
    configureAuth({
      enableTestTokens: true,
      defaultTenantId: 'default',
      securityServiceUrl: 'http://localhost:6008',
    });
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  // -----------------------------------------------------------------------
  // parseTestToken
  // -----------------------------------------------------------------------

  describe('parseTestToken', () => {
    it('returns null when test tokens are disabled', () => {
      configureAuth({ enableTestTokens: false });
      const token = buildTestToken({ sub: 'u1', role: 'user' });
      expect(parseTestToken(token)).toBeNull();
    });

    it('returns a UserPayload for a valid test token', () => {
      const token = buildTestToken({ sub: 'u1', role: 'admin', email: 'a@b.com' });
      const result = parseTestToken(token);
      expect(result).not.toBeNull();
      expect(result!.userId).toBe('u1');
      expect(result!.role).toBe('admin');
      expect(result!.email).toBe('a@b.com');
    });

    it('returns null for tokens without the test prefix', () => {
      expect(parseTestToken('not_a_test_token')).toBeNull();
    });

    it('returns null when required fields are missing', () => {
      const token = buildTestToken({ sub: 'u1' }); // missing role
      expect(parseTestToken(token)).toBeNull();
    });

    it('returns null for expired test tokens', () => {
      const token = buildTestToken({ sub: 'u1', role: 'user', exp: Date.now() - 10000 });
      expect(parseTestToken(token)).toBeNull();
    });

    it('returns null in production environment', () => {
      vi.stubEnv('NODE_ENV', 'production');
      const token = buildTestToken({ sub: 'u1', role: 'user' });
      expect(parseTestToken(token)).toBeNull();
    });
  });

  // -----------------------------------------------------------------------
  // authenticateToken
  // -----------------------------------------------------------------------

  describe('authenticateToken', () => {
    it('RED KS-1198: an sk_ key validated on the API-key path attaches the validated key metadata as req.connectorMeta, scopes intact, for the connector gates to read', async () => {
      const meta = { connectorId: 'c-meta', scopes: ['documents:write'], organizationId: 'org1', tenantId: 't1', tenantSlug: 'one', rateLimit: 100, rateLimitWindow: 60 };
      apiKeyCache.set('sk_meta', { result: meta, expiresAt: Date.now() + 60000 });
      fetchMock.mockResolvedValue({ ok: true, json: async () => ({ data: {} }) });
      const req = makeReq({ headers: { 'x-api-key': 'sk_meta' } });
      const res = makeRes(), next = vi.fn();
      await authenticateToken(true)(req, res as any, next);
      expect([next.mock.calls.length, res._status, (req as any).user?.role, (req as any).connectorMeta]).toEqual([1, 0, 'connector', meta]);
    });
    it('skips auth when required=false and no token is present', async () => {
      const req = makeReq();
      const res = makeRes();
      const next = vi.fn();

      await authenticateToken(false)(req, res as any, next);

      expect(next).toHaveBeenCalled();
      expect(res._status).toBe(0);
    });

    it('rejects with 401 when required=true and no token is present', async () => {
      const req = makeReq();
      const res = makeRes();
      const next = vi.fn();

      await authenticateToken(true)(req, res as any, next);

      expect(next).not.toHaveBeenCalled();
      expect(res._status).toBe(401);
      expect(res._json).toEqual({ success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } });
    });

    it('accepts a valid JWT and populates req.user', async () => {
      const payload: UserPayload = {
        userId: 'u42',
        email: 'u42@secuura.io',
        role: 'user',
        verificationLevel: 'standard',
      };
      const token = signJwt(payload);
      const req = makeReq({ headers: { authorization: `Bearer ${token}` } });
      const res = makeRes();
      const next = vi.fn();

      await authenticateToken()(req, res as any, next);

      expect(next).toHaveBeenCalled();
      expect((req as any).user.userId).toBe('u42');
      expect(req.headers['x-user-id']).toBe('u42');
    });

    it('rejects an expired JWT with 401', async () => {
      const token = signJwt(
        { userId: 'u1', email: 'e', role: 'user', verificationLevel: 'basic' },
        TEST_SECRET,
        { expiresIn: '-1s' },
      );
      const req = makeReq({ headers: { authorization: `Bearer ${token}` } });
      const res = makeRes();
      const next = vi.fn();

      await authenticateToken(true)(req, res as any, next);

      expect(next).not.toHaveBeenCalled();
      expect(res._status).toBe(401);
      expect(res._json).toEqual({ success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid or expired token' } });
    });

    it('assigns defaultTenantId when JWT has no tenantId', async () => {
      const token = signJwt({
        userId: 'u1',
        email: 'e@e.com',
        role: 'user',
        verificationLevel: 'basic',
      });
      const req = makeReq({ headers: { authorization: `Bearer ${token}` } });
      const res = makeRes();
      const next = vi.fn();

      await authenticateToken()(req, res as any, next);

      expect(next).toHaveBeenCalled();
      expect((req as any).user.tenantId).toBe('default');
    });
    it('RED KS-1244: a repeated x-api-key (two individually valid keys joined by Node) on a required mount is refused 401 with no principal and no Bearer fall-through, in either order', async () => {
      const meta = { connectorId: 'c-joined', scopes: ['read'], organizationId: 'org1', tenantId: 't1', tenantSlug: 'one', rateLimit: 100, rateLimitWindow: 60 };
      apiKeyCache.set('sk_first', { result: meta, expiresAt: Date.now() + 60000 });
      apiKeyCache.set('sk_second', { result: meta, expiresAt: Date.now() + 60000 });
      fetchMock.mockResolvedValue({ ok: true, json: async () => ({ data: { valid: false } }) });
      const outcomes: unknown[] = [];
      for (const joined of ['sk_first, sk_second', 'sk_second, sk_first']) {
        const req = makeReq({ headers: { 'x-api-key': joined, authorization: 'Bearer ' + buildTestToken({ sub: 'u-beside', role: 'user' }) } });
        const res = makeRes();
        const next = vi.fn();
        await authenticateToken(true)(req, res as any, next);
        outcomes.push([joined, next.mock.calls.length, res._status, res._json?.success, res._json?.error?.code, (req as any).user?.role]);
      }
      expect(outcomes).toEqual([['sk_first, sk_second', 0, 401, false, 'UNAUTHORIZED', undefined], ['sk_second, sk_first', 0, 401, false, 'UNAUTHORIZED', undefined]]);
    });
  });

  // -----------------------------------------------------------------------
  // validateApiKey
  // -----------------------------------------------------------------------

  describe('validateApiKey', () => {
    it('validates sk_ prefixed keys via Security Service', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          data: {
            valid: true,
            connectorId: 'c1',
            scopes: ['read'],
            organizationId: 'org1',
            rateLimit: 200,
            rateLimitWindow: 60,
          },
        }),
      });

      const result = await validateApiKey('sk_test123');

      expect(result).not.toBeNull();
      expect(result!.connectorId).toBe('c1');
      expect(result!.scopes).toEqual(['read']);
    });

    it('returns null for invalid keys', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ data: { valid: false } }),
      });

      const result = await validateApiKey('sk_bad');
      expect(result).toBeNull();
    });

    it('returns cached result on subsequent calls within TTL', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          data: { valid: true, connectorId: 'c2', scopes: [], organizationId: 'o', rateLimit: 100, rateLimitWindow: 60 },
        }),
      });

      const first = await validateApiKey('sk_cached');
      const second = await validateApiKey('sk_cached');

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(second).toEqual(first);
    });

    it('caches null for invalid keys and does not re-fetch within TTL', async () => {
      fetchMock.mockResolvedValueOnce({
        ok: false,
        json: async () => ({}),
      });

      const first = await validateApiKey('sk_invalid');
      const second = await validateApiKey('sk_invalid');

      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(first).toBeNull();
      expect(second).toBeNull();
    });

    it('returns null when fetch throws', async () => {
      fetchMock.mockRejectedValueOnce(new Error('network error'));
      const result = await validateApiKey('sk_fail');
      expect(result).toBeNull();
    });
  });
});
